// Task 0146 (slice 2): the .tri morph reader, the weighted sum and the loudness-driven mouth, on generated bytes (no
// game files). Written before the implementation and run red against a stub.
#include <components/trimorph/mouth.hpp>
#include <components/trimorph/trimorph.hpp>

#include <gtest/gtest.h>

#include <cmath>
#include <cstdint>
#include <cstring>
#include <limits>
#include <string>
#include <vector>

namespace
{
    void put32(std::string& s, std::uint32_t v)
    {
        for (int i = 0; i < 4; ++i)
            s.push_back(static_cast<char>((v >> (8 * i)) & 0xff));
    }

    void putf(std::string& s, float f)
    {
        std::uint32_t v;
        std::memcpy(&v, &f, 4);
        put32(s, v);
    }

    void put16(std::string& s, std::int16_t v)
    {
        const auto u = static_cast<std::uint16_t>(v);
        s.push_back(static_cast<char>(u & 0xff));
        s.push_back(static_cast<char>(u >> 8));
    }

    struct MorphSpec
    {
        std::string name;
        float scale;
        std::vector<std::int16_t> deltas;
    };

    struct Spec
    {
        std::uint32_t vertices = 2;
        std::uint32_t triangles = 1;
        std::uint32_t quads = 0;
        std::uint32_t labelVerts = 0;
        std::uint32_t surfLabelVerts = 0;
        std::uint32_t texCoords = 0;
        std::uint32_t flags = 0;
        std::uint32_t staticMorphs = 0;
        std::uint32_t modifiers = 0;
        std::uint32_t modifierVerts = 0;
        std::vector<MorphSpec> morphs;
        std::string magic = "FRTRI003";
        std::string trailing;
        bool nameWithNul = false;
    };

    std::string makeTri(const Spec& s)
    {
        std::string b = s.magic;
        put32(b, s.vertices);
        put32(b, s.triangles);
        put32(b, s.quads);
        put32(b, s.labelVerts);
        put32(b, s.surfLabelVerts);
        put32(b, s.texCoords);
        put32(b, s.flags);
        put32(b, static_cast<std::uint32_t>(s.morphs.size()));
        put32(b, s.staticMorphs);
        put32(b, s.modifiers);
        put32(b, s.modifierVerts);
        put32(b, 0);
        b.append(8, '\0');
        for (std::uint32_t v = 0; v < s.vertices; ++v)
            for (int k = 0; k < 3; ++k)
                putf(b, static_cast<float>(v * 3 + k));
        for (std::uint32_t t = 0; t < s.triangles; ++t)
            for (int k = 0; k < 3; ++k)
                put32(b, 0);
        if (s.flags & 1)
        {
            for (std::uint32_t t = 0; t < s.texCoords; ++t)
            {
                putf(b, 0.5f);
                putf(b, 0.25f);
            }
            for (std::uint32_t t = 0; t < s.triangles; ++t)
                for (int k = 0; k < 3; ++k)
                    put32(b, 0);
        }
        for (const MorphSpec& m : s.morphs)
        {
            const std::string name = m.name + (s.nameWithNul ? std::string(1, '\0') : std::string());
            put32(b, static_cast<std::uint32_t>(name.size()));
            b += name;
            putf(b, m.scale);
            for (std::int16_t d : m.deltas)
                put16(b, d);
        }
        return b + s.trailing;
    }

    Spec twoMorphs()
    {
        Spec s;
        s.morphs.push_back({ "Aah", 0.5f, { 2, 0, 0, 0, -4, 0 } });
        s.morphs.push_back({ "BigAah", 0.25f, { 0, 8, 0, 0, 0, 12 } });
        return s;
    }

    TEST(TriMorphRead, readsTheHeaderAndMorphsInFileOrder)
    {
        const std::string bytes = makeTri(twoMorphs());
        const TriMorph::Result r = TriMorph::read(bytes, "a.tri");
        ASSERT_TRUE(r.mOk) << r.mError;
        EXPECT_EQ(r.mFile.mVertices, 2u);
        EXPECT_EQ(r.mFile.mMorphsInFile, 2u);
        ASSERT_EQ(r.mFile.mMorphs.size(), 2u);
        EXPECT_EQ(r.mFile.mMorphs[0].mName, "Aah");
        EXPECT_FLOAT_EQ(r.mFile.mMorphs[0].mScale, 0.5f);
        EXPECT_EQ(r.mFile.mMorphs[0].mDeltas, (std::vector<std::int16_t>{ 2, 0, 0, 0, -4, 0 }));
        EXPECT_EQ(r.mFile.mMorphs[1].mName, "BigAah");
        EXPECT_EQ(r.mFile.mMorphs[1].mDeltas, (std::vector<std::int16_t>{ 0, 8, 0, 0, 0, 12 }));
        EXPECT_EQ(r.mFile.mTrailingBytes, 0u);
        EXPECT_TRUE(r.mError.empty());
    }

    TEST(TriMorphRead, skipsTheTextureCoordinateSectionWhenTheFlagIsSet)
    {
        Spec s = twoMorphs();
        s.flags = 1;
        s.texCoords = 2;
        const TriMorph::Result r = TriMorph::read(makeTri(s), "a.tri");
        ASSERT_TRUE(r.mOk) << r.mError;
        ASSERT_EQ(r.mFile.mMorphs.size(), 2u);
        EXPECT_EQ(r.mFile.mMorphs[1].mDeltas[1], 8);
    }

    TEST(TriMorphRead, aTrailingNulOfTheNameIsDropped)
    {
        Spec s = twoMorphs();
        s.nameWithNul = true;
        const TriMorph::Result r = TriMorph::read(makeTri(s), "a.tri");
        ASSERT_TRUE(r.mOk) << r.mError;
        EXPECT_EQ(r.mFile.mMorphs[0].mName, "Aah");
    }

    TEST(TriMorphRead, keepsOnlyTheWantedMorphsWithoutRegardToCase)
    {
        const std::string bytes = makeTri(twoMorphs());
        const std::vector<std::string_view> wanted{ "bigaah", "Missing" };
        const TriMorph::Result r = TriMorph::read(bytes, "a.tri", wanted);
        ASSERT_TRUE(r.mOk) << r.mError;
        EXPECT_EQ(r.mFile.mMorphsInFile, 2u);
        ASSERT_EQ(r.mFile.mMorphs.size(), 1u);
        EXPECT_EQ(r.mFile.mMorphs[0].mName, "BigAah");
    }

    TEST(TriMorphRead, countsTrailingBytes)
    {
        Spec s = twoMorphs();
        s.trailing = "xyz";
        const TriMorph::Result r = TriMorph::read(makeTri(s), "a.tri");
        ASSERT_TRUE(r.mOk) << r.mError;
        EXPECT_EQ(r.mFile.mTrailingBytes, 3u);
    }

    TEST(TriMorphRead, aFileWithNoMorphsIsLegal)
    {
        Spec s;
        const TriMorph::Result r = TriMorph::read(makeTri(s), "a.tri");
        ASSERT_TRUE(r.mOk) << r.mError;
        EXPECT_TRUE(r.mFile.mMorphs.empty());
    }

    TEST(TriMorphRead, refusesAWrongMagicAndSaysWhere)
    {
        Spec s = twoMorphs();
        s.magic = "FRTRI002";
        const TriMorph::Result r = TriMorph::read(makeTri(s), "head.tri");
        EXPECT_FALSE(r.mOk);
        EXPECT_NE(r.mError.find("head.tri"), std::string::npos);
        EXPECT_NE(r.mError.find("offset"), std::string::npos);
    }

    TEST(TriMorphRead, refusesLayoutsItNeverSaw)
    {
        const auto refused = [](void (*change)(Spec&)) {
            Spec s = twoMorphs();
            change(s);
            return !TriMorph::read(makeTri(s), "a.tri").mOk;
        };
        EXPECT_TRUE(refused([](Spec& s) { s.quads = 1; }));
        EXPECT_TRUE(refused([](Spec& s) { s.labelVerts = 1; }));
        EXPECT_TRUE(refused([](Spec& s) { s.surfLabelVerts = 1; }));
        EXPECT_TRUE(refused([](Spec& s) { s.staticMorphs = 1; }));
        EXPECT_TRUE(refused([](Spec& s) { s.modifiers = 1; }));
        EXPECT_TRUE(refused([](Spec& s) { s.modifierVerts = 1; }));
    }

    TEST(TriMorphRead, refusesCountsOverTheLimitsBeforeAllocating)
    {
        TriMorph::Limits limits;
        limits.mMaxVertices = 1;
        EXPECT_FALSE(TriMorph::read(makeTri(twoMorphs()), "a.tri", {}, limits).mOk);
        limits = {};
        limits.mMaxMorphsInFile = 1;
        EXPECT_FALSE(TriMorph::read(makeTri(twoMorphs()), "a.tri", {}, limits).mOk);
        limits = {};
        limits.mMaxBytes = 100;
        EXPECT_FALSE(TriMorph::read(makeTri(twoMorphs()), "a.tri", {}, limits).mOk);
        limits = {};
        limits.mMaxNameLength = 2;
        EXPECT_FALSE(TriMorph::read(makeTri(twoMorphs()), "a.tri", {}, limits).mOk);
        // A hostile count in the header of an otherwise small file (patched, not generated: it must not be allocated).
        for (const std::uint32_t count : { 0x7fffffffu, 0xffffffffu })
        {
            std::string patched = makeTri(twoMorphs());
            for (int i = 0; i < 4; ++i)
                patched[8 + static_cast<std::size_t>(i)] = static_cast<char>((count >> (8 * i)) & 0xff);
            EXPECT_FALSE(TriMorph::read(patched, "a.tri").mOk);
        }
    }

    TEST(TriMorphRead, refusesANonFiniteScale)
    {
        Spec s = twoMorphs();
        s.morphs[0].scale = std::numeric_limits<float>::quiet_NaN();
        EXPECT_FALSE(TriMorph::read(makeTri(s), "a.tri").mOk);
        s.morphs[0].scale = std::numeric_limits<float>::infinity();
        EXPECT_FALSE(TriMorph::read(makeTri(s), "a.tri").mOk);
    }

    TEST(TriMorphRead, everyTruncationIsRefused)
    {
        Spec s = twoMorphs();
        s.flags = 1;
        s.texCoords = 2;
        const std::string bytes = makeTri(s);
        for (std::size_t n = 0; n < bytes.size(); ++n)
        {
            const TriMorph::Result r = TriMorph::read(std::string_view(bytes).substr(0, n), "a.tri");
            EXPECT_FALSE(r.mOk) << "length " << n;
        }
        EXPECT_TRUE(TriMorph::read(bytes, "a.tri").mOk);
    }

    TEST(TriMorphRead, aNameLengthPastTheEndOrNegativeIsRefused)
    {
        std::string bytes = makeTri(twoMorphs());
        const std::size_t nameLengthAt = 64 + 2 * 12 + 1 * 12; // header, vertices, one triangle
        std::string big = bytes;
        big[nameLengthAt] = '\xff';
        big[nameLengthAt + 1] = '\xff';
        big[nameLengthAt + 2] = '\xff';
        big[nameLengthAt + 3] = '\x7f';
        EXPECT_FALSE(TriMorph::read(big, "a.tri").mOk);
        big[nameLengthAt + 3] = '\xff';
        EXPECT_FALSE(TriMorph::read(big, "a.tri").mOk);
    }

    TEST(TriMorphRead, survivesTwentyThousandMutations)
    {
        Spec s = twoMorphs();
        s.flags = 1;
        s.texCoords = 2;
        const std::string original = makeTri(s);
        std::uint32_t state = 12345;
        const auto next = [&state] {
            state = state * 1664525u + 1013904223u;
            return state >> 8;
        };
        std::size_t accepted = 0;
        for (int i = 0; i < 20000; ++i)
        {
            std::string m = original;
            const int edits = 1 + static_cast<int>(next() % 4);
            for (int e = 0; e < edits; ++e)
                m[next() % m.size()] = static_cast<char>(next() & 0xff);
            const TriMorph::Result r = TriMorph::read(m, "a.tri");
            if (r.mOk)
            {
                ++accepted;
                EXPECT_LE(r.mFile.mMorphs.size(), r.mFile.mMorphsInFile);
                for (const TriMorph::Morph& morph : r.mFile.mMorphs)
                    EXPECT_EQ(morph.mDeltas.size(), static_cast<std::size_t>(r.mFile.mVertices) * 3);
            }
            else
                EXPECT_FALSE(r.mError.empty());
        }
        EXPECT_GT(accepted, 0u); // edits of delta bytes are legal
    }

    // ---- apply

    using Vec = std::array<float, 3>;

    TriMorph::File parsed(const Spec& s)
    {
        const TriMorph::Result r = TriMorph::read(makeTri(s), "a.tri");
        EXPECT_TRUE(r.mOk) << r.mError;
        return r.mFile;
    }

    TEST(TriMorphApply, addsWeightTimesScaleTimesDelta)
    {
        const TriMorph::File file = parsed(twoMorphs());
        const std::vector<Vec> base{ { 1.f, 1.f, 1.f }, { 2.f, 2.f, 2.f } };
        std::vector<Vec> out(2);
        const TriMorph::Term terms[] = { { 0, 1.f } };
        ASSERT_TRUE(TriMorph::apply(file, base, terms, out));
        // Aah: scale 0.5, deltas (2,0,0) and (0,-4,0)
        EXPECT_FLOAT_EQ(out[0][0], 2.f);
        EXPECT_FLOAT_EQ(out[0][1], 1.f);
        EXPECT_FLOAT_EQ(out[1][1], 0.f);
        EXPECT_FLOAT_EQ(out[1][0], 2.f);
    }

    TEST(TriMorphApply, sumsTermsAndScalesByTheWeight)
    {
        const TriMorph::File file = parsed(twoMorphs());
        const std::vector<Vec> base(2, Vec{ 0.f, 0.f, 0.f });
        std::vector<Vec> out(2);
        const TriMorph::Term terms[] = { { 0, 0.5f }, { 1, 2.f } };
        ASSERT_TRUE(TriMorph::apply(file, base, terms, out));
        // vertex 0: Aah x: 0.5*0.5*2 = 0.5; BigAah y: 2*0.25*8 = 4
        EXPECT_FLOAT_EQ(out[0][0], 0.5f);
        EXPECT_FLOAT_EQ(out[0][1], 4.f);
        // vertex 1: Aah y: 0.5*0.5*-4 = -1; BigAah z: 2*0.25*12 = 6
        EXPECT_FLOAT_EQ(out[1][1], -1.f);
        EXPECT_FLOAT_EQ(out[1][2], 6.f);
    }

    TEST(TriMorphApply, noTermsCopiesTheBase)
    {
        const TriMorph::File file = parsed(twoMorphs());
        const std::vector<Vec> base{ { 1.f, 2.f, 3.f }, { 4.f, 5.f, 6.f } };
        std::vector<Vec> out(2, Vec{ 9.f, 9.f, 9.f });
        ASSERT_TRUE(TriMorph::apply(file, base, {}, out));
        EXPECT_EQ(out, base);
    }

    TEST(TriMorphApply, skipsNonFiniteWeights)
    {
        const TriMorph::File file = parsed(twoMorphs());
        const std::vector<Vec> base(2, Vec{ 0.f, 0.f, 0.f });
        std::vector<Vec> out(2);
        const TriMorph::Term terms[] = { { 0, std::numeric_limits<float>::quiet_NaN() }, { 1, 1.f } };
        ASSERT_TRUE(TriMorph::apply(file, base, terms, out));
        EXPECT_FLOAT_EQ(out[0][0], 0.f);
        EXPECT_FLOAT_EQ(out[0][1], 2.f);
    }

    TEST(TriMorphApply, aBadTermIndexOrSizeWritesNothing)
    {
        const TriMorph::File file = parsed(twoMorphs());
        const std::vector<Vec> base(2, Vec{ 0.f, 0.f, 0.f });
        const Vec marker{ 7.f, 7.f, 7.f };
        std::vector<Vec> out(2, marker);
        const TriMorph::Term bad[] = { { 5, 1.f } };
        EXPECT_FALSE(TriMorph::apply(file, base, bad, out));
        EXPECT_EQ(out[0], marker);
        std::vector<Vec> wrong(3, marker);
        const TriMorph::Term good[] = { { 0, 1.f } };
        EXPECT_FALSE(TriMorph::apply(file, base, good, wrong));
        EXPECT_EQ(wrong[2], marker);
        const std::vector<Vec> shortBase(1, Vec{ 0.f, 0.f, 0.f });
        EXPECT_FALSE(TriMorph::apply(file, shortBase, good, out));
        EXPECT_EQ(out[0], marker);
    }

    TEST(TriMorphApply, theSameStorageForBaseAndOutIsFine)
    {
        const TriMorph::File file = parsed(twoMorphs());
        std::vector<Vec> both{ { 1.f, 1.f, 1.f }, { 2.f, 2.f, 2.f } };
        const TriMorph::Term terms[] = { { 0, 1.f } };
        ASSERT_TRUE(TriMorph::apply(file, both, terms, both));
        EXPECT_FLOAT_EQ(both[0][0], 2.f);
    }

    TEST(TriMorphApply, aMorphFilteredOutOfTheFileCannotBeIndexed)
    {
        const std::vector<std::string_view> wanted{ "Aah" };
        const TriMorph::Result r = TriMorph::read(makeTri(twoMorphs()), "a.tri", wanted);
        ASSERT_TRUE(r.mOk);
        const std::vector<Vec> base(2, Vec{ 0.f, 0.f, 0.f });
        std::vector<Vec> out(2);
        const TriMorph::Term terms[] = { { 1, 1.f } };
        EXPECT_FALSE(TriMorph::apply(r.mFile, base, terms, out));
    }

    // ---- the mouth

    TEST(Mouth, silenceKeepsTheMouthClosed)
    {
        TriMorph::MouthDrive drive;
        for (int i = 0; i < 10; ++i)
            EXPECT_EQ(drive.step(0.f), TriMorph::MouthWeights{});
    }

    TEST(Mouth, aLoudLineOpensTheJawAndTheBigMorphOnlyWhenWide)
    {
        TriMorph::MouthDrive drive;
        TriMorph::MouthWeights w;
        for (int i = 0; i < 30; ++i)
            w = drive.step(1.f);
        EXPECT_GT(w.mAah, 0.5f);
        EXPECT_LE(w.mAah, TriMorph::kAahMax + 1e-6f);
        EXPECT_GT(w.mBigAah, 0.f);
        TriMorph::MouthDrive soft;
        for (int i = 0; i < 30; ++i)
            w = soft.step(0.05f);
        EXPECT_GT(w.mAah, 0.f);
        EXPECT_EQ(w.mBigAah, 0.f);
    }

    TEST(Mouth, theJawOpensFasterThanItCloses)
    {
        TriMorph::MouthDrive drive;
        drive.step(1.f);
        const float opened = drive.openness();
        EXPECT_GT(opened, TriMorph::kAttack * 0.99f); // took the attack share of the way from 0 to a target of 1
        TriMorph::MouthDrive closing;
        for (int i = 0; i < 40; ++i)
            closing.step(1.f);
        const float before = closing.openness();
        closing.step(0.f);
        const float closedBy = before - closing.openness();
        EXPECT_GT(closedBy, 0.f);
        EXPECT_LT(closedBy, before); // not shut in one step
        EXPECT_LT(closedBy / before, TriMorph::kAttack); // slower than opening
    }

    TEST(Mouth, nonFiniteAndNegativeLoudnessCountAsSilence)
    {
        TriMorph::MouthDrive drive;
        EXPECT_EQ(drive.step(std::numeric_limits<float>::quiet_NaN()), TriMorph::MouthWeights{});
        EXPECT_EQ(drive.step(-3.f), TriMorph::MouthWeights{});
        EXPECT_EQ(drive.step(std::numeric_limits<float>::infinity()).mAah >= 0.f, true);
        EXPECT_TRUE(std::isfinite(drive.openness()));
    }

    TEST(Mouth, weightsAreMultiplesOfOneSixteenth)
    {
        TriMorph::MouthDrive drive;
        for (int i = 0; i < 50; ++i)
        {
            const TriMorph::MouthWeights w = drive.step(0.1f + 0.017f * static_cast<float>(i % 7));
            for (float x : { w.mAah, w.mBigAah })
            {
                const float scaled = x * static_cast<float>(TriMorph::kMouthSteps);
                EXPECT_NEAR(scaled, std::round(scaled), 1e-4f);
                EXPECT_GE(x, 0.f);
                EXPECT_LE(x, 1.f);
            }
        }
    }

    TEST(Mouth, theLoudnessWeightsBecomeTheFirstTwoVisemes)
    {
        const TriMorph::VisemeWeights v = TriMorph::toVisemes({ 0.5f, 0.25f });
        EXPECT_EQ(v[0], 0.5f);
        EXPECT_EQ(v[1], 0.25f);
        for (std::size_t i = 2; i < v.size(); ++i)
            EXPECT_EQ(v[i], 0.f);
    }

    TEST(Mouth, quantiseClampsAndRounds)
    {
        EXPECT_EQ(TriMorph::quantise(-1.f), 0.f);
        EXPECT_EQ(TriMorph::quantise(2.f), 1.f);
        EXPECT_EQ(TriMorph::quantise(std::numeric_limits<float>::quiet_NaN()), 0.f);
        EXPECT_FLOAT_EQ(TriMorph::quantise(0.5f), 0.5f);
        EXPECT_FLOAT_EQ(TriMorph::quantise(0.51f), 0.5f);
        EXPECT_FLOAT_EQ(TriMorph::quantise(0.04f), 0.0625f);
    }

    TEST(Mouth, resetClosesTheMouthAndTheSameInputsGiveTheSameWeights)
    {
        TriMorph::MouthDrive a;
        TriMorph::MouthDrive b;
        for (int i = 0; i < 20; ++i)
            EXPECT_EQ(a.step(0.3f * static_cast<float>(i % 3)), b.step(0.3f * static_cast<float>(i % 3)));
        a.reset();
        EXPECT_EQ(a.openness(), 0.f);
    }
}
